INSERT INTO products (category_id, name, slug, description, price, discount, stock, active, featured, main_image_url) VALUES
('c4444444-4444-4444-4444-444444444444', 'Porta Esponja Plastico', 'porta-esponja-plastico-71623', 'Porta Esponja Plástico Institucional Organización y secado higiénico para estaciones de limpieza y cocinas El porta esponja plástico es un insumo técnico esencial para mantener el orden y la higiene en áreas de lavado, cocinas industriales y laboratorios. Fabricado en polímeros de alta densidad, este accesorio es resistente a la humedad constante y al contacto con detergentes agresivos, evitando la acumulación de residuos de jabón en las superficies. Como herramienta de aseo institucional, su diseño permite un drenaje eficiente del agua, acelerando el secado de la fibra o esponja para prevenir la proliferación de bacterias y malos olores. Es una solución compacta, duradera y de fácil instalación que optimiza el espacio de trabajo y prolonga la vida útil de sus elementos de limpieza.', 15811.00, 20, 42, true, false, 'https://www.abastece.co/abastece/images/71623.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Porta Mechas Plastico Sin Mango Ref : 060 Fuller Pinto', 'porta-mechas-plastico-sin-mango-ref-060-fuller-pinto-71608', 'Porta Mechas Plastico Sin Mango Ref 060 Fuller Pinto Practicidad y durabilidad para tu trabajo de mecanica El Porta Mechas Plastico Sin Mango Ref 060 Fuller Pinto es una herramienta esencial para tus tareas de perforacion. Hecho de plastico resistente, proporciona un agarre seguro para tus mechas, garantizando precision y control al trabajar. Su diseño sin mango lo hace ideal para una mayor versatilidad en espacios reducidos o donde se requiera un manejo mas directo. ¡Aumenta la eficiencia y durabilidad de tus proyectos con este porta mechas de alta calidad!', 11027.00, 20, 44, true, false, 'https://www.abastece.co/abastece/images/71608.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Protector Brillador Para Pisos De Madera 1900ML Binner 1908 108185', 'protector-brillador-para-pisos-de-madera-1900ml-binner-1908-108185-8396', 'Protector Brillador para Pisos de Madera 1900 ml Binner 1908 Protección y Brillo Duradero para tus Pisos de Madera El Protector Brillador para Pisos de Madera 1900 ml Binner 1908 está diseñado para proporcionar un acabado brillante y duradero a tus pisos de madera. Su fórmula avanzada protege la superficie contra el desgaste y la suciedad, mientras le da un brillo natural que resalta la belleza de la madera. Ideal para uso doméstico y comercial, este protector no solo mejora la apariencia de tus pisos, sino que también aumenta su resistencia a la abrasión y al daño causado por el tráfico pesado. Con un envase de 1900 ml, obtendrás un suministro adecuado para múltiples aplicaciones, asegurando que tus pisos se mantengan impecables por más tiempo.', 38821.00, 20, 20, true, false, 'https://www.abastece.co/abastece/images/8396.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Protector Brillador Para Pisos De Porcelanato Binner 1900 Ml 111454', 'protector-brillador-para-pisos-de-porcelanato-binner-1900-ml-111454-73310', 'Protector Brillador para Pisos de Porcelanato Binner 1900 ml Cuidado especializado y brillo superior para superficies de alta gama El Protector Brillador Binner para Porcelanato es un insumo técnico de alta eficiencia diseñado para mantener la elegancia y el brillo natural de los pisos más exigentes. Su fórmula avanzada crea una película protectora que previene el desgaste prematuro, facilita la limpieza diaria y resalta la luminosidad de la superficie sin dejar huellas ni residuos grasos. Como insumo de aseo profesional, este producto de 1900 ml es ideal para oficinas, recepciones y áreas comerciales que cuentan con pisos de porcelanato o cerámica de alto tráfico. Es un producto de higiene institucional indispensable para garantizar que sus espacios mantengan una apariencia impecable y profesional, prolongando la vida útil de sus revestimientos mediante un mantenimiento especializado de alto rendimiento.', 31042.00, 20, 20, true, false, 'https://www.abastece.co/abastece/images/73310.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Punto Ecologico 53 Lt Blanco-Negro-Verde Tapa Vaiven.', 'punto-ecologico-53-lt-blanco-negro-verde-tapa-vaiven-76220', 'Punto Ecológico 53 Litros (Blanco, Negro, Verde) para Reciclaje Estación de clasificación integral para el cumplimiento del código de colores El Punto Ecológico de 53 litros es la solución técnica definitiva para las empresas comprometidas con la gestión responsable de residuos. Compuesto por tres contenedores de alta capacidad en colores blanco, negro y verde, este sistema facilita el cumplimiento estricto de la normativa vigente sobre separación en la fuente (Resolución 2184). Su estructura robusta y señalización clara permiten una segregación eficiente de residuos aprovechables, no aprovechables y orgánicos. Como insumo de aseo profesional, este punto ecológico es ideal para zonas comunes, pasillos, cafeterías y centros de producción de alto tráfico. Es un producto de higiene institucional duradero y de fácil mantenimiento, diseñado para fomentar la cultura del reciclaje y optimizar los procesos de limpieza y logística de residuos en grandes instalaciones corporativas.', 243995.00, 20, 38, true, false, 'https://www.abastece.co/abastece/images/76220.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Punto Ecologico Vaiven 10 Lt Blanco-Negro- Verde Estra', 'punto-ecologico-vaiven-10-lt-blanco-negro-verde-estra-77086', 'Punto Ecológico Vaivén 10 Litros (Blanco, Negro, Verde) - Marca Estra Solución compacta para la clasificación de residuos en oficinas y consultorios El Punto Ecológico Vaivén Estra de 10 litros es la estación de reciclaje perfecta para espacios interiores que requieren eficiencia y cumplimiento normativo en un diseño reducido. Este conjunto de tres papeleras (blanco, negro y verde) permite la correcta aplicación del código de colores nacional (Resolución 2184) para la separación de residuos aprovechables, no aprovechables y orgánicos. Gracias a su sistema de tapa oscilante (vaivén), garantiza que los desechos permanezcan fuera de la vista, manteniendo la estética y la higiene del lugar. Como insumo de aseo profesional, su fabricación en polímero de alta resistencia asegura durabilidad y facilidad de limpieza. Es un producto de higiene institucional esencial para empresas que buscan promover la sostenibilidad en estaciones de trabajo, salas de espera y áreas administrativas de tráfico moderado.', 133035.00, 20, 25, true, false, 'https://www.abastece.co/abastece/images/77086.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Punto Ecologico Vaiven 35 Lts Blanco-Verde-Negro Fuller Pinto', 'punto-ecologico-vaiven-35-lts-blanco-verde-negro-fuller-pinto-3453', 'Punto Ecologico Vaiven 35 Lts Blanco-Verde-Negro Fuller Pinto Solucion Ecologica y Practica para la Gestion de Residuos El Punto Ecologico Vaiven 35 Lts Blanco-Verde-Negro Fuller Pinto es una opcion ideal para promover el reciclaje y la gestion de residuos de manera eficiente y ecologica. Con un diseño practico y resistente, este punto de reciclaje cuenta con una capacidad de 35 litros y un sistema de colores que facilita la separacion de los diferentes tipos de residuos. Perfecto para oficinas, hogares y espacios publicos, este producto no solo ayuda a organizar y optimizar el manejo de basura, sino que tambien contribuye al cuidado del medio ambiente.', 346619.00, 20, 37, true, false, 'https://www.abastece.co/abastece/images/3453.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Punto Ecologico Vaiven 35Lts Blanco Negro Estra', 'punto-ecologico-vaiven-35lts-blanco-negro-estra-74918', 'Punto Ecológico Vaivén 35 Litros (Blanco y Negro) - Marca Estra Estación de reciclaje funcional para la gestión de residuos aprovechables y no aprovechables El Punto Ecológico Vaivén Estra de 35 litros es una solución técnica y estética diseñada para facilitar la separación de residuos en entornos profesionales de tráfico medio. Este conjunto binario, compuesto por contenedores en colores blanco y negro, permite dar cumplimiento a la normativa vigente para la clasificación de residuos aprovechables (plástico, vidrio, metales limpios) y no aprovechables (papel higiénico, servilletas, cartón contaminado). Gracias a su sistema de tapa oscilante (vaivén), garantiza que los desechos permanezcan fuera de la vista, promoviendo la higiene y el orden en oficinas, pasillos y áreas de servicios generales. Como insumo de aseo profesional, su fabricación en materiales de alta resistencia asegura durabilidad y facilidad de limpieza, consolidándose como un producto de higiene institucional clave para la sostenibilidad corporativa.', 143237.00, 20, 31, true, false, 'https://www.abastece.co/abastece/images/74918.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Punto Ecologico Vaiven Colplast Blanco/Verde/Negro 22lt', 'punto-ecologico-vaiven-colplast-blancoverdenegro-22lt-75255', 'Punto Ecológico Vaivén 22 Litros Colplast (Blanco, Verde, Negro) Estación intermedia para la segregación técnica de residuos institucionales El punto ecológico Colplast de 22 litros es un insumo técnico de tamaño intermedio, diseñado para estaciones de reciclaje en pasillos, oficinas y áreas comunes. Este sistema triple incluye tapas tipo vaivén que facilitan una disposición rápida y estética de residuos aprovechables, orgánicos y ordinarios. Como herramienta de aseo institucional, destaca por su fabricación en polímero resistente de fácil limpieza, permitiendo una señalización clara y el cumplimiento eficiente de la normativa ambiental en espacios de tráfico moderado.', 134400.00, 20, 34, true, false, 'https://www.abastece.co/abastece/images/75255.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Punto Ecologico Vaiven Fuller Pinto Blanco-Verde-Negro 55Lt', 'punto-ecologico-vaiven-fuller-pinto-blanco-verde-negro-55lt-3505', 'Punto Ecologico Vaiven 55 Lts Blanco-Verde-Negro - Fuller Pinto Solucion ecologica y practica para la gestion de residuos El Punto Ecologico Vaiven 55 Lts Blanco-Verde-Negro de Fuller Pinto es una opcion perfecta para quienes buscan una solucion eficaz y respetuosa con el medio ambiente para la disposicion de residuos. Con una capacidad de 55 litros, este punto ecologico esta diseñado para facilitar la separacion y el reciclaje de materiales, promoviendo practicas mas sostenibles en tu hogar, oficina o espacio publico. Los colores blanco, verde y negro permiten una facil identificacion para la clasificacion de desechos reciclables, organicos y no reciclables. Fabricado con materiales resistentes y de alta calidad, garantiza durabilidad y un funcionamiento practico. ¡Haz tu parte por el medio ambiente con el Punto Ecologico Vaiven Fuller Pinto!', 404354.00, 20, 26, true, false, 'https://www.abastece.co/abastece/images/3505.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Rastrillo Plastico De 21 A 26 Dientes Con Mango', 'rastrillo-plastico-de-21-a-26-dientes-con-mango-5741', 'Rastrillo Plástico de 21 a 26 Dientes con Mango: La Herramienta Perfecta para tu Jardín Características y Beneficios del Rastrillo Plástico El Rastrillo Plástico de 21 a 26 Dientes con Mango es ideal para aquellos que buscan una herramienta resistente y ligera para el cuidado de su jardín. Su diseño ergonómico y su mango cómodo permiten una sujeción firme y un manejo sencillo, mientras que sus dientes plásticos de alta calidad aseguran un rendimiento óptimo, perfectos para recoger hojas, hierba y residuos de jardín. Disponible en varias opciones de tamaño, es una herramienta versátil que se adapta a tus necesidades de jardinería. ¡Haz que tu jardín luzca impecable con el mejor rastrillo del mercado!', 7566.00, 20, 15, true, false, 'https://www.abastece.co/abastece/images/5741.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Recogedor De Mano Plastico Con Cepillo', 'recogedor-de-mano-plastico-con-cepillo-72205', 'Recogedor de Mano Plástico con Cepillo Set de limpieza compacto para superficies y estaciones de trabajo El set de recogedor y cepillo de mano es un insumo esencial para la limpieza rápida de escritorios, teclados y áreas reducidas en oficinas. Fabricado en plástico resistente, su diseño ergonómico permite recoger residuos pequeños con facilidad, optimizando el mantenimiento de estaciones de trabajo. Es un producto de higiene institucional ligero y duradero, ideal para mantener espacios impecables de forma inmediata.', 14725.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/72205.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Recogedor De Mano Plastico Con Cepillo My', 'recogedor-de-mano-plastico-con-cepillo-my-74555', 'Recogedor de Mano Plástico con Cepillo My Herramienta práctica para limpieza focalizada en oficinas El recogedor de mano con cepillo My es un accesorio compacto diseñado para la limpieza rápida de superficies elevadas y puestos de trabajo. Fabricado en polímero resistente, permite remover polvo y residuos pequeños de escritorios de forma eficiente. Es un insumo de aseo institucional ligero y de fácil almacenamiento, ideal para mantener el orden inmediato en cualquier entorno corporativo.', 5830.00, 20, 17, true, false, 'https://www.abastece.co/abastece/images/74555.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Recogedor Mango Plastico Con Banda', 'recogedor-mango-plastico-con-banda-2490', 'Recogedor Mango Plástico con Banda: Calidad y Durabilidad en la Limpieza del Hogar Descubre el recogedor de alta resistencia con mango de plástico y banda incorporada para una limpieza eficiente y sin esfuerzo. Confeccionado con materiales duraderos, garantiza una recolección eficaz de residuos y suciedad en cualquier superficie. ¡Calidad y comodidad para tu hogar en un solo producto!', 3775.00, 20, 32, true, false, 'https://www.abastece.co/abastece/images/2490.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Recogedor Repuesto Con Banda Sin Mango', 'recogedor-repuesto-con-banda-sin-mango-3652', 'Recogedor Respuesto Conn Banda Sin Mango: Calidad y Durabilidad en la Limpieza del Hogar Descubre el recogedor de alta resistencia con banda incorporada para una limpieza eficiente y sin esfuerzo. Confeccionado con materiales duraderos, garantiza una recolección eficaz de residuos y suciedad en cualquier superficie. ¡Calidad y comodidad para tu hogar en un solo producto!', 2720.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/3652.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Removedor De Ceras Full Fresh Desincrustante 3875ml', 'removedor-de-ceras-full-fresh-desincrustante-3875ml-75491', 'Desincrustante Removedor de Ceras Full Fresh 3875 ml: Preparación Profesional de Pisos Insumo Técnico de Alta Potencia para la Limpieza Profunda y Restauración de Superficies Prepare sus superficies para un acabado impecable con el Desincrustante Removedor de Ceras Full Fresh de 3875 ml. Este potente agente químico está diseñado para eliminar acumulaciones antiguas de ceras, selladores y suciedad incrustada que los limpiadores convencionales no logran remover. Su fórmula avanzada actúa profundamente sobre los poros del piso, facilitando la remoción de capas amarillentas o desgastadas en superficies de baldosa, granito y caucho, devolviendo la apariencia original del material. Gracias a su presentación en galón, garantiza un rendimiento superior para grandes áreas institucionales y comerciales, optimizando el tiempo de trabajo de los equipos de servicios generales. Es la herramienta indispensable para coordinadores de mantenimiento que buscan realizar procesos de decapado profesional antes de una nueva aplicación de ceras o selladores, asegurando una adherencia perfecta y un brillo renovado en las instalaciones.', 41478.00, 20, 28, true, false, 'https://www.abastece.co/abastece/images/75491.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Removedor De Ceras Para Pisos Madera Y Laminados 1900 Ml 200498', 'removedor-de-ceras-para-pisos-madera-y-laminados-1900-ml-200498-73315', 'Removedor de Ceras para Pisos Madera y Laminados 1900 ml: ¡Limpieza Profunda y Efectiva! Devuelve la Belleza Natural a tus Superficies Presentamos el Removedor de Ceras para Pisos Madera y Laminados en un generoso envase de 1900 ml, diseñado para eliminar capas de cera acumuladas y restaurar el brillo original de tus superficies. Su fórmula potente actúa rápidamente, facilitando la limpieza sin dañar la madera ni los laminados. Ideal para uso doméstico o profesional, este removedor es la solución perfecta para mantener tus pisos en óptimas condiciones. ¡Renueva tus espacios y disfruta de un acabado impecable!', 37852.00, 20, 48, true, false, 'https://www.abastece.co/abastece/images/73315.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Removedor de Ceras y Selladores Orion 3750 ml', 'removedor-de-ceras-y-selladores-orion-3750-ml-73316', 'Removedor de Ceras y Selladores Orion 3750 ml La Solución Eficaz para la Limpieza y Restauración de Pisos El Removedor de Ceras y Selladores Orion 3750 ml es el producto ideal para eliminar capas de ceras y selladores de pisos de manera rápida y eficiente. Su fórmula potente garantiza una limpieza profunda, dejando superficies libres de residuos y listas para ser tratadas con nuevos acabados. Perfecto para uso en empresas de mantenimiento y limpieza de pisos, ofreciendo resultados profesionales en cada aplicación.', 24998.00, 20, 29, true, false, 'https://www.abastece.co/abastece/images/73316.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Removedor Potente De Ceras Y Selladores 20lt', 'removedor-potente-de-ceras-y-selladores-20lt-5320', '-Producto concentrado -Penetra profundamente sobre las superficies, removiendo ceras y selladores -No deja residuos que levanten el recubrimiento posterior; ahorra tiempo y esfuerzo Descargar ficha técnica', 37632.00, 20, 54, true, false, 'https://www.abastece.co/abastece/images/5320.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Removedor Potente De Ceras Y Selladores 3000ml', 'removedor-potente-de-ceras-y-selladores-3000ml-0538', '-Producto concentrado -Penetra profundamente sobre las superficies, removiendo ceras y selladores -No deja residuos que levanten el recubrimiento posterior; ahorra tiempo y esfuerzo Descargar ficha técnica', 17262.00, 20, 47, true, false, 'https://www.abastece.co/abastece/images/0538.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Repuesto Limpiador De Telarañas', 'repuesto-limpiador-de-telaranas-72234', 'Repuesto Limpiador de Telarañas Elimina eficazmente las telarañas en tu hogar o oficina El repuesto limpiador de telarañas es la herramienta perfecta para eliminar fácilmente las telarañas de cualquier rincón. Su diseño eficaz y material de alta calidad permite una limpieza rápida y sin esfuerzo, manteniendo tus espacios siempre ordenados y libres de polvo. ¡Haz la limpieza más fácil y eficiente con este repuesto de alta durabilidad!', 4552.00, 20, 35, true, false, 'https://www.abastece.co/abastece/images/72234.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Repuesto Recogedor Plastico Con Banda Azul', 'repuesto-recogedor-plastico-con-banda-azul-77143', 'Repuesto Recogedor Plástico con Banda Azul Componente de alta precisión para sistemas de recolección de residuos El repuesto de recogedor plástico con banda azul es un insumo técnico diseñado para prolongar la vida útil de sus equipos de limpieza institucional. Su borde con banda de goma flexible asegura un contacto hermético con el suelo, permitiendo la captura eficiente de polvo fino y partículas pequeñas sin dejar residuos. Como herramienta de aseo institucional, este cabezal de polímero resistente es ideal para programas de codificación por colores en áreas administrativas y comerciales, ofreciendo una solución económica y sostenible al permitir el reemplazo de la pieza de desgaste sin cambiar el mango.', 3986.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/77143.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Repuesto Recogedor Plastico Con Banda Blanco', 'repuesto-recogedor-plastico-con-banda-blanco-77144', 'Recogedor Plástico con Mango y Banda de Goma - Blanco Diseño ergonómico con ajuste perfecto al suelo para un barrido eficaz Este recogedor plástico con mango destaca por su banda de goma flexible que asegura un contacto total con el piso, evitando que el polvo se filtre por debajo. Su estructura liviana y ergonómica facilita las jornadas de limpieza extendidas en oficinas y locales. Es un insumo de aseo institucional duradero y funcional, ideal para mantener la higiene impecable en áreas administrativas y comerciales.', 3986.00, 20, 21, true, false, 'https://www.abastece.co/abastece/images/77144.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Repuesto Recogedor Plastico Con Banda Rojo', 'repuesto-recogedor-plastico-con-banda-rojo-77145', 'Repuesto Recogedor Plástico con Banda Rojo Componente especializado para protocolos de limpieza por codificación de color El repuesto de recogedor plástico con banda rojo es un insumo técnico de alta resistencia, diseñado para integrarse en sistemas de limpieza segregados por áreas de riesgo o zonas sanitarias. Su banda de goma flexible en el borde permite un sellado perfecto con la superficie, garantizando la recolección total de polvo y residuos sólidos. Como herramienta de aseo institucional, este cabezal permite optimizar costos operativos al reemplazar únicamente la pieza de contacto, manteniendo los estándares de higiene y durabilidad exigidos en entornos industriales y de salud.', 3986.00, 20, 34, true, false, 'https://www.abastece.co/abastece/images/77145.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Repuesto Trapero Microfibra Rojo 300 Gr Task Pro', 'repuesto-trapero-microfibra-rojo-300-gr-task-pro-76048', 'Repuesto Trapero Microfibra Rojo 300 Gr Task Pro Mopa de alta absorción para limpieza técnica y desinfección de superficies El repuesto trapero de microfibra Task Pro de 300 gramos es un insumo técnico de alto rendimiento, diseñado para la limpieza húmeda en áreas que requieren estrictos protocolos de codificación por colores. Su composición de microfibras permite una absorción superior y la captura de partículas microscópicas sin dejar pelusas ni rastros. Como herramienta de aseo institucional, su color rojo facilita la segregación en zonas críticas o sanitarias, garantizando durabilidad ante el uso intensivo y una reducción significativa en el consumo de químicos y agua gracias a su eficiencia mecánica.', 14635.00, 20, 40, true, false, 'https://www.abastece.co/abastece/images/76048.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Sanitizante Scott Desinf. De Manos Y Brazos Spray 400ml 30241782/30246455', 'sanitizante-scott-desinf-de-manos-y-brazos-spray-400ml-3024178230246455-3339', 'Sanitizante Scott Spray 400ml para Manos y Brazos Desinfección de alto rendimiento y secado rápido para entornos corporativos El sanitizante Scott en spray de 400ml es un insumo técnico diseñado para garantizar la higiene instantánea en manos y brazos sin necesidad de enjuague. Su fórmula profesional elimina eficazmente gérmenes y bacterias, siendo ideal para áreas de alto contacto y protocolos de bioseguridad. Como producto de higiene institucional, su formato en spray permite una aplicación uniforme y eficiente, convirtiéndose en un aliado clave para oficinas, consultorios y estaciones de servicio que priorizan la salud y el bienestar.', 35976.00, 20, 49, true, false, 'https://www.abastece.co/abastece/images/3339.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Secador Caucho Piso 38 Cms Con Mango 150Cms Fuller', 'secador-caucho-piso-38-cms-con-mango-150cms-fuller-74075', 'Secador Caucho Piso 38 Cms Con Mango 150Cms Fuller Una herramienta efectiva para mantener tus pisos impecables El Secador Caucho Piso 38 Cms con Mango de 150 Cms Fuller es ideal para mantener tus espacios limpios y secos de manera rápida y eficiente. Su diseño con un amplio cabezal de caucho de 38 cm permite una excelente cobertura, mientras que el mango de 150 cm ofrece comodidad y control para un uso prolongado sin esfuerzo. Perfecto para limpiar superficies de pisos en hogares, oficinas o comercios. ¡Haz que tu tarea de secado sea más fácil y efectiva con el secador Fuller!', 26890.00, 20, 18, true, false, 'https://www.abastece.co/abastece/images/74075.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Secador Caucho Piso 60Cms C.Mango 150Cms Fuller Pinto', 'secador-caucho-piso-60cms-cmango-150cms-fuller-pinto-3661', 'Secador Caucho Piso 60 Cms con Mango 150 Cms Fuller Pinto Rendimiento y Comodidad para la Limpieza de Pisos El Secador Caucho Piso 60 Cms con Mango 150 Cms Fuller Pinto es la herramienta ideal para limpiar grandes superficies de manera eficiente. Con un ancho de 60 cm, este secador de piso cuenta con una goma resistente que asegura un secado rapido y efectivo. Su mango de 150 cm proporciona un alcance comodo y facil manejo, permitiendo realizar tareas de limpieza sin tener que agacharse o forzar la postura. Perfecto para su uso en hogares, oficinas, instalaciones comerciales o cualquier espacio que requiera un secado profesional y rapido de pisos.', 39326.00, 20, 53, true, false, 'https://www.abastece.co/abastece/images/3661.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Secador De Manos Automatico Infrarrojo En Acero Inoxidable', 'secador-de-manos-automatico-infrarrojo-en-acero-inoxidable-74972', 'Secador de Manos Automático Infrarrojo en Acero Inoxidable Tecnología de secado higiénico y eficiente para áreas de alto tráfico El secador de manos automático infrarrojo es un insumo técnico de alta gama diseñado para optimizar la higiene en baños institucionales. Fabricado en acero inoxidable de gran durabilidad y resistencia al vandalismo, cuenta con un sensor de precisión que activa el flujo de aire sin necesidad de contacto físico, reduciendo el riesgo de contaminación cruzada. Como herramienta de aseo institucional, representa una solución sostenible y de bajo mantenimiento que elimina el uso de toallas de papel, garantizando un secado rápido y eficiente en centros comerciales, oficinas y entornos industriales.', 454579.00, 20, 34, true, false, 'https://www.abastece.co/abastece/images/74972.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Sellador Neutro Para Pisos Orion 3750 Ml', 'sellador-neutro-para-pisos-orion-3750-ml-77000', 'Sellador Neutro para Pisos Orion 3750 ml Protección especializada y brillo duradero para superficies institucionales El sellador neutro Orion es un insumo técnico diseñado para proteger y resaltar la apariencia de diversos tipos de pisos en áreas de alto tráfico. Su fórmula balanceada crea una capa resistente que facilita el mantenimiento diario y previene el desgaste prematuro de la superficie. Como producto de aseo profesional, este galón de 3750 ml asegura un rendimiento óptimo en oficinas, pasillos y zonas comerciales, garantizando una imagen impecable y profesional en sus instalaciones.', 99124.00, 20, 34, true, false, 'https://www.abastece.co/abastece/images/77000.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Sellador Para Pisos Antideslizante Orion 3750 Ml', 'sellador-para-pisos-antideslizante-orion-3750-ml-72746', 'Sellador Para Pisos Antideslizante ORION – Galón x 3750 ml Cuando el brillo también cumple una función operativa Sellador acrílico autobrillante de alto desempeño, con propiedad antideslizante, diseñado para superficies sometidas a tránsito frecuente. Presentación en galón de 3750 ml (3,75 L), con consistencia líquida, tono blanco lechoso y secado rápido. Compatible con vinilo, mármol, granito, concreto, baldosín, ladrillo y cerámica no vitrificada, forma una película uniforme que reduce el desgaste mecánico y mantiene una apariencia homogénea sin requerir pulido. Su formulación biodegradable permite integrarlo como insumo estratégico dentro de esquemas de estandarización y continuidad operativa, optimizando rutinas de mantenimiento, minimizando reprocesos y consolidando entornos más seguros, ordenados y funcionales para el equipo.', 93907.00, 20, 16, true, false, 'https://www.abastece.co/abastece/images/72746.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Sellador Para Pisos Autobrillante Potente 20 Litros', 'sellador-para-pisos-autobrillante-potente-20-litros-5679', '-Antideslizante y resistente a rayones -Alto nivel de brillo -Producto libre de fragancia -Ideal para proteger los pisos de alto tránsito -Apta para granito, cerámica, baldosa y caucho Descargar ficha técnica', 446880.00, 20, 46, true, false, 'https://www.abastece.co/abastece/images/5679.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Sellador Para Pisos Autobrillante Potente 3000 Ml', 'sellador-para-pisos-autobrillante-potente-3000-ml-5386', 'Sellador para Pisos 3000 ML Potente: Protección y Brillo Duraderos Antideslizante y Resistente a Rayones para Pisos de Alto Tránsito Ideal para Granito, Cerámica, Baldosa y Caucho El Sellador para Pisos 3000 ML Potente es la solución perfecta para proteger y realzar la belleza de tus pisos. Su fórmula avanzada proporciona una capa protectora que es antideslizante y resistente a rayones, asegurando una mayor durabilidad incluso en áreas de alto tránsito. Disfruta de un alto nivel de brillo que realza la apariencia de tus pisos, dejándolos lucir como nuevos. Además, este sellador es libre de fragancia, lo que lo hace ideal para personas sensibles a los olores fuertes. Descargar ficha técnica', 80841.00, 20, 16, true, false, 'https://www.abastece.co/abastece/images/5386.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Sellador Para Pisos Full Fresh 3785 Ml Ref 624', 'sellador-para-pisos-full-fresh-3785-ml-ref-624-76509', 'Sellador para Pisos Full Fresh 3785 ml (Ref. 624) Protección de alto tráfico y brillo antideslizante para pisos institucionales El sellador para pisos Full Fresh es un insumo técnico de alta densidad diseñado para proteger superficies del desgaste diario y agentes químicos. Su fórmula proporciona un acabado brillante y antideslizante, facilitando la limpieza y mejorando la estética en áreas comunes. Como producto de aseo institucional, este galón de 3785 ml es ideal para el mantenimiento profesional en oficinas, centros comerciales y zonas de producción, garantizando una mayor vida útil para sus pisos.', 90002.00, 20, 30, true, false, 'https://www.abastece.co/abastece/images/76509.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Shampoo La Joya Para Fibras Y Alfombras 1000 Ml', 'shampoo-la-joya-para-fibras-y-alfombras-1000-ml-5501', 'Revitaliza tus Alfombras con Shampoo La Joya Especializado para Fibras Potente Limpieza Profunda y Restauración Fórmula Avanzada para fibras y alfombras, elimina manchas y renueva la Suavidad Disfruta de alfombras impecables y suavidad unica. ¡Cuida tus espacios con el poder de la limpieza profesional!', 20029.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/5501.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Shampoo Muebles Alfombras Lavanda Full Fresh 3785 ml', 'shampoo-muebles-alfombras-lavanda-full-fresh-3785-ml-9388', 'Shampoo para Muebles y Alfombras Lavanda Full Fresh 3785 ml La Solución Perfecta para Espacios Impecables Transforma tus muebles y alfombras con el shampoo de lavanda Full Fresh, presentado en un conveniente formato de 3785 ml. Este producto está especialmente formulado para eliminar manchas y olores, dejando tus superficies limpias y con un delicado aroma a lavanda que revitaliza cualquier ambiente. Su acción profunda asegura una limpieza eficaz sin dañar los tejidos, haciéndolo ideal para el uso diario. ¡Renueva tus espacios y disfruta de un hogar fresco y acogedor!', 23690.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/9388.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Shampoo Para Alfombras Tapetes Y Muebles Orion 1000 Ml', 'shampoo-para-alfombras-tapetes-y-muebles-orion-1000-ml-3656', 'Shampoo Para Alfombras, Tapetes y Muebles Orión 1000 ml Limpieza profunda y fragancia duradera El Shampoo Orión está especialmente formulado para la limpieza de alfombras, tapetes y muebles. Su presentación de 1000 ml ofrece un alto rendimiento y efectividad para remover manchas, suciedad y malos olores, dejando las superficies limpias y frescas. Características: &amp;#10004;&amp;#65039; Contenido: 1000 ml &amp;#10004;&amp;#65039; Aplicación: Alfombras, tapetes, muebles tapizados &amp;#10004;&amp;#65039; Aroma: Fresco y agradable &amp;#10004;&amp;#65039; Fácil de usar y enjuagar &amp;#10004;&amp;#65039; Marca: Orión', 4290.00, 20, 29, true, false, 'https://www.abastece.co/abastece/images/3656.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Silicona Multiusos Proteccion UV Potente 3000 Ml', 'silicona-multiusos-proteccion-uv-potente-3000-ml-5713', '-Formula balanceada que proporciona limpieza, brillo y protección -Contiene protector UV -Fragancia chicle. Notas dulces que deja en el ambiente sensación agradable -Humecta y recupera el brillo del cuero, vinilo, caucho, madera entre otros. Descargar ficha técnica', 54542.00, 20, 22, true, false, 'https://www.abastece.co/abastece/images/5713.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Silicona Protector Alto Brillo UV3 300 Ml Carro Nuevo Simoniz', 'silicona-protector-alto-brillo-uv3-300-ml-carro-nuevo-simoniz-3886', 'Silicona Protectora Alto Brillo UV3 Simoniz - 300 ml Protección avanzada contra rayos UV y renovación de superficies La Silicona Simoniz UV3 es un insumo técnico de alta eficiencia para proteger y embellecer superficies de vinilo, caucho y plástico. Su fórmula de alto brillo crea una barrera protectora contra los rayos solares, evitando la decoloración y el agrietamiento. Como producto de aseo profesional, es ideal para el mantenimiento de flotas vehiculares y mobiliario de oficina, garantizando un acabado renovado y duradero con aroma a carro nuevo.', 14818.00, 20, 20, true, false, 'https://www.abastece.co/abastece/images/3886.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Silicona Protector Alto Brillo UV3 300 Ml Chicle Simoniz', 'silicona-protector-alto-brillo-uv3-300-ml-chicle-simoniz-3885', 'Silicona Protectora Alto Brillo UV3 Simoniz - 300 ml (Chicle) Brillo superior y fragancia prolongada para superficies de vinilo y caucho La Silicona Simoniz UV3 Chicle es un insumo técnico que combina protección avanzada y aromatización. Su fórmula protectora contra rayos UV previene el agrietamiento y la decoloración en tableros, partes plásticas y cueros sintéticos. Como producto de aseo institucional, es ideal para el mantenimiento de flotas de transporte y mobiliario, proporcionando un acabado de alto brillo con un agradable aroma a chicle que perdura en el ambiente.', 14722.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/3885.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Talco Mexana Frasco 300g + Mexana 85g.', 'talco-mexana-frasco-300g-mexana-85g-74659', 'Talco Mexana Frasco 300g + 85g Protección desodorante y cuidado para la salud del personal El talco Mexana es un insumo esencial para el cuidado personal y la higiene en el entorno laboral. Su fórmula medicinal ayuda a prevenir la humedad y el mal olor, garantizando frescura y comodidad durante jornadas extensas. Como producto de higiene institucional, este kit de 300g más una presentación viajera de 85g es ideal para dotar botiquines, vestuarios y áreas de bienestar en empresas que priorizan la salud de sus colaboradores.', 20818.00, 20, 36, true, false, 'https://www.abastece.co/abastece/images/74659.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Tapete Atrapamugre 90 X 60 Alto Trafico Color Negro', 'tapete-atrapamugre-90-x-60-alto-trafico-color-negro-73217', 'Tapete Atrapamugre 90 x 60 cm - Alto Tráfico Negro Barrera de limpieza eficiente para entradas y áreas de alto flujo El tapete atrapamugre de alto tráfico es un insumo técnico diseñado para retener suciedad y humedad en los accesos de oficinas y locales comerciales. Su estructura de rizo de PVC permite una limpieza profunda de la suela del calzado, protegiendo los pisos interiores del desgaste. Como producto de aseo institucional en color negro, ofrece una apariencia profesional y gran durabilidad, siendo una solución esencial para mantener la higiene y seguridad en zonas de tránsito constante.', 120070.00, 20, 37, true, false, 'https://www.abastece.co/abastece/images/73217.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Toalla Blanca x5 Metros Continuos', 'toalla-blanca-x5-metros-continuos-70276', 'Toalla Blanca 5 Metros Continuos: Suavidad y Absorción para Cada Necesidad La Toalla Ideal para Uso Personal, Comercial o Industrial La Toalla Blanca de 5 Metros Continuos es perfecta para quienes buscan un producto versátil, absorbente y de alta calidad. Con 5 metros continuos de toalla, este producto es ideal para una amplia gama de usos, desde el hogar hasta negocios como hoteles, spas, salones de belleza o incluso en entornos industriales. Su suave textura y alta capacidad de absorción hacen que sea perfecta para secado de manos, limpieza, o para envolver objetos delicados. Además, su color blanco le da un toque de elegancia y frescura, y su presentación en rollo continuo permite un uso eficiente y económico. ¡Optimiza tus tareas de higiene y limpieza con la Toalla Blanca de 5 Metros Continuos!', 39439.00, 20, 15, true, false, 'https://www.abastece.co/abastece/images/70276.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Toalla De Manos Center Pull Blanca 100mts Paq.x6  Doble Hoja Sanitisu Ref: 530220302', 'toalla-de-manos-center-pull-blanca-100mts-paqx6-doble-hoja-sanitisu-ref-530220302-76065', 'Toalla de Manos Center Pull Blanca Sanitisu (Paquete x6) Higiene eficiente con sistema de dispensación central y doble hoja La toalla de manos Center Pull Sanitisu de 100 metros es un insumo técnico diseñado para garantizar una higiene óptima en baños y áreas de producción de alto flujo. Su sistema de extracción central permite un control de consumo eficiente, mientras que su fabricación en doble hoja ofrece una absorción superior y resistencia al uso. Como producto de aseo institucional, este paquete de 6 rollos es la solución ideal para empresas que buscan rendimiento, suavidad y una reducción en el desperdicio de papel.', 69736.00, 20, 39, true, false, 'https://www.abastece.co/abastece/images/76065.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Toalla De Manos Center Pull Natural 100mts X 6 D.Hoja Sanitisu Ref: 530220303', 'toalla-de-manos-center-pull-natural-100mts-x-6-dhoja-sanitisu-ref-530220303-76066', 'Toalla de Manos Center Pull Natural Sanitisu (Paquete x6) Resistencia y sostenibilidad con sistema de extracción central doble hoja La toalla de manos Center Pull Natural Sanitisu de 100 metros combina eficiencia y un enfoque más sostenible para la higiene corporativa. Su color natural y fabricación en doble hoja proporcionan una excelente resistencia y absorción para el secado de manos. Como insumo de aseo institucional, su formato de dispensación central (Ref: 530220303) garantiza un uso controlado y fluido, siendo ideal para cocinas industriales, talleres y baños de alto tráfico.', 60043.00, 20, 50, true, false, 'https://www.abastece.co/abastece/images/76066.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Toalla De Manos En Z Elite Doble H. Blanca Fajo X150 Hojas 631004', 'toalla-de-manos-en-z-elite-doble-h-blanca-fajo-x150-hojas-631004-3842', 'Toalla de Manos en Z Elite Doble H Blanca Fajo x150 Hojas 631004 Comodidad y Eficiencia para un Secado Rapido La Toalla de Manos en Z Elite Doble H Blanca Fajo x150 Hojas 631004 es la opcion perfecta para mantener la higiene y comodidad en cualquier espacio. Su diseño en Z permite un facil dispensado, asegurando un acceso rapido a cada hoja sin desperdiciar papel. Con 150 hojas por fajos, estas toallas de alta calidad ofrecen una excelente capacidad de absorcion, garantizando un secado efectivo y rapido. Ideal para baños de oficinas, restaurantes o instituciones, proporciona una solucion economica y practica para mantener la limpieza en todo momento.', 5389.00, 20, 37, true, false, 'https://www.abastece.co/abastece/images/3842.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Toalla De Manos En Z Elite H.Doble Natural Paq.x150u. 631003', 'toalla-de-manos-en-z-elite-hdoble-natural-paqx150u-631003-74127', 'Toalla de Manos en Z Elite HD Natural Paq x150 Ref 631003 Higiene y conveniencia con cada uso Las Toallas de Manos en Z Elite HD Natural Paq x150 Ref 631003 son ideales para mantener la higiene en tu hogar o negocio. Con un diseño práctico y económico, estas toallas ofrecen una absorción superior y son perfectas para baños, oficinas o áreas de alto tráfico.', 5326.00, 20, 21, true, false, 'https://www.abastece.co/abastece/images/74127.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Toalla De Manos Familia 100m Natural T.H Paq x6 Ref 73689', 'toalla-de-manos-familia-100m-natural-th-paq-x6-ref-73689-5606', 'Toalla de Manos Flujo Central Famimax natural hoja triple rollo x 100 m Ref:73687 Reduce el desperdicio y evita los malos usos Maximo rendimiento, mayor absorcion y resistencia con su precorte preciso que garantiza el dispensado una a una, sin necesidad de tocar el dispensador. Caracteristicas del producto -Rollo de 100 m -Hoja Triple -Natural -Precortado -Paca X6 Rollos Beneficios del producto -Una sola toalla es suficiente. -Bienestar superior a los usuarios entregandoles mayor suavidad en el secado. -Cada rollo proporciona 488 hojas. Una paca de 6 rollos alcanza para 2.200 secadas de manos aproximadamente. Descargar ficha tecnica', 126653.00, 20, 21, true, false, 'https://www.abastece.co/abastece/images/5606.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Toalla De Manos Familia 2 Rollos X100m Natural Doble H 73618', 'toalla-de-manos-familia-2-rollos-x100m-natural-doble-h-73618-9118', 'Ref:73615 -Toalla de Manos-Flujo Central -natural -hoja doble -rollo x 100 m -La unión de sus dos hojas proporciona la abosrbencia, resistencia y suavidad adecuadas. Características del producto -Rollo de 100 m -Hoja Doble -Precortado -Natural Beneficios del producto -Empaque por 3 paquetes, cada uno por dos rollos provee mayor higiene facilitando su distribución y almacenamiento. -Gracias a su precorte dispensa una a una sin necesidad de tocar el dispensador. -Cada rollo proporciona 488 hojas que permiten abastecer buen número de usuarios. Descargar ficha técnica', 46315.00, 20, 20, true, false, 'https://www.abastece.co/abastece/images/9118.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Toalla De Manos Familia 6 Rollos X120m Natural Doble H 73748', 'toalla-de-manos-familia-6-rollos-x120m-natural-doble-h-73748-5003', 'Toalla de Manos Familia 6 Rollos x120m Natural Doble H - N/P: 73748 Descripción del Producto La Toalla de Manos Familia 6 Rollos x120m Natural Doble H es perfecta para el uso diario en hogares, oficinas o negocios. Cada rollo tiene 120 metros de longitud, lo que proporciona un gran rendimiento y durabilidad. Su textura suave y absorbente garantiza una experiencia confortable al secar las manos. El color natural de la toalla combina con cualquier ambiente, mientras que su formato de 6 rollos asegura que tengas suficiente suministro por un largo periodo. Con la calidad y confiabilidad de la marca Doble H, es la opción ideal para quienes buscan eficiencia y practicidad en productos de higiene.', 122.00, 20, 54, true, false, 'https://www.abastece.co/abastece/images/5003.jpg')
